from typing import Optional

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def rob(self, root: Optional[TreeNode]) -> int:
        def dfs(node):
            if not node:
                return (0, 0)
            left_rob, left_skip = dfs(node.left)
            right_rob, right_skip = dfs(node.right)
            rob_curr = node.val + left_skip + right_skip
            skip_curr = max(left_rob, left_skip) + max(right_rob, right_skip)
            return (rob_curr, skip_curr)

        return max(dfs(root))

class Solution {
    pair<int, int> dfs(TreeNode* node) {
        if (!node) return {0, 0};
        auto left = dfs(node->left);
        auto right = dfs(node->right);
        int robCurr = node->val + left.second + right.second;
        int skipCurr = max(left.first, left.second) + max(right.first, right.second);
        return {robCurr, skipCurr};
    }
public:
    int rob(TreeNode* root) {
        auto res = dfs(root);
        return max(res.first, res.second);
    }
};

class Solution {
    private int[] dfs(TreeNode node) {
        if (node == null) return new int[]{0, 0};
        int[] left = dfs(node.left);
        int[] right = dfs(node.right);
        int robCurr = node.val + left[1] + right[1];
        int skipCurr = Math.max(left[0], left[1]) + Math.max(right[0], right[1]);
        return new int[]{robCurr, skipCurr};
    }

    public int rob(TreeNode root) {
        int[] res = dfs(root);
        return Math.max(res[0], res[1]);
    }
}

var rob = function(root) {
    function dfs(node) {
        if (!node) return [0, 0];
        const [leftRob, leftSkip] = dfs(node.left);
        const [rightRob, rightSkip] = dfs(node.right);
        const robCurr = node.val + leftSkip + rightSkip;
        const skipCurr = Math.max(leftRob, leftSkip) + Math.max(rightRob, rightSkip);
        return [robCurr, skipCurr];
    }

    const [r, s] = dfs(root);
    return Math.max(r, s);
};
